let inventoryProofOpen=false;
function requestInventoryProof(title){
  if(inventoryProofOpen)return Promise.resolve(null);
  inventoryProofOpen=true;
  return new Promise(resolve=>{
    const dialog=document.createElement('dialog');dialog.className='system-dialog';
    dialog.innerHTML='<form><div class="modal-title"><h2></h2></div><div class="modal-body"><p>El ajuste requiere una explicación y un documento de respaldo.</p><label class="field"><span>Motivo obligatorio</span><textarea name="reason" required minlength="8" rows="3"></textarea></label><label class="field"><span>Folio o referencia del documento</span><input name="reference" required /></label><label class="field"><span>Evidencia obligatoria</span><input name="evidence" type="file" accept="image/*,.pdf" required /></label><p role="alert" class="proof-error"></p></div><div class="modal-actions"><button type="button" class="cancel">Cancelar</button><button type="submit" class="submit">Validar respaldo</button></div></form>';
    dialog.querySelector('h2').textContent=title;
    const finish=value=>{inventoryProofOpen=false;dialog.close();dialog.remove();resolve(value)};
    dialog.querySelector('.cancel').onclick=()=>finish(null);
    dialog.addEventListener('cancel',event=>{event.preventDefault();finish(null)});
    dialog.querySelector('form').onsubmit=async event=>{
      event.preventDefault();const form=event.currentTarget,button=form.querySelector('.submit'),selection=validMediaFiles(form.elements.evidence.files);
      if(!selection.valid||!selection.files.length){dialog.querySelector('.proof-error').textContent='Adjunta una imagen o PDF de máximo 5 MB.';return}
      button.disabled=true;
      try{const id=newMovement({}).id,records=await storeMediaRecords('movementEvidence','movementId',id,selection.files),proof={id,reason:form.elements.reason.value.trim(),reference:form.elements.reference.value.trim(),evidence:records.map(({id,name,type,size,hash,createdAt})=>({id,name,type,size,hash,createdAt}))},error=window.BioInventoryProof.validate(proof);if(error)throw new Error(error);finish(proof)}catch(error){dialog.querySelector('.proof-error').textContent=error.message||'No se pudo conservar el respaldo. El inventario no se modificó.';button.disabled=false}
    };
    document.body.append(dialog);dialog.showModal();
  });
}
