function supplierLatestPriceListAt(supplierId,fallbackDate=null){
  const id=String(supplierId),timestamps=[
    ...priceLoads.filter(load=>String(load.supplierId)===id).map(load=>load.appliedAt||load.createdAt),
    ...priceCatalogEntries.filter(entry=>String(entry.supplierId)===id).map(entry=>entry.appliedAt||entry.validFrom||entry.createdAt),
    ...products.filter(product=>String(product.supplierId)===id).map(product=>product.lastPriceListAt),
    fallbackDate
  ].map(value=>({value,time:Date.parse(value||'')})).filter(candidate=>Number.isFinite(candidate.time));
  return timestamps.sort((a,b)=>b.time-a.time)[0]?.value||null;
}
