['catalogPrice','productEditPrice','productEditSalePrice'].forEach(id=>$('#'+id)?.addEventListener('input',event=>{const required=id!=='productEditSalePrice',result=validateManualPriceField(event.currentTarget,{required,maxDecimals:4});if(result.valid)window.BioFormValidation?.clearFieldError?.(event.currentTarget)}));
const supportedCurrencies=['USD','CAD','MXN','EUR'];
function detectCurrency(value){const raw=String(value??''),text=normalizeHeader(raw);if(/\bCAD\b|\bCDN\b|CANAD|DOLAR CAN/.test(text)||raw.includes('C$'))return 'CAD';if(/\bEUR\b|EURO/.test(text)||raw.includes('€'))return 'EUR';if(/\bMXN\b|PESO MEX|MEXICAN PESO|MONEDA NACIONAL/.test(text)||raw.includes('MX$'))return 'MXN';if(/\bUSD\b|DOLAR(?:ES)? AMERIC|US DOLLAR/.test(text)||raw.includes('US$'))return 'USD';if(/\bDOLAR(?:ES)?\b/.test(text))return 'USD';return ''}
