function showToast(msg,requestedKind){const message=String(msg||''),el=$('#toast');if(!el)return;const now=Date.now();if(showToast.lastMessage===message&&now-Number(showToast.lastAt||0)<1200)return;showToast.lastMessage=message;showToast.lastAt=now;const kind=['success','error'].includes(requestedKind)?requestedKind:feedbackKind(message),entry={message,kind,at:new Date().toISOString()},records=[entry,...operationFeedback()].slice(0,30);try{sessionStorage.setItem(OPERATION_FEEDBACK_KEY,JSON.stringify(records))}catch{}installOperationFeedback();const counter=$('#operationFeedbackButton b');if(counter)counter.textContent=records.length;const openDialogs=[...document.querySelectorAll('dialog[open]')],host=openDialogs.at(-1)||document.body;if(el.parentElement!==host)host.append(el);el.setAttribute('role',kind==='error'?'alert':'status');el.textContent=`${kind==='success'?'✓':'⚠'} ${message}`;el.className=`show ${kind}`;clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>{el.classList.remove('show');setTimeout(()=>{if(!document.querySelector('dialog[open]')&&el.parentElement!==document.body)document.body.append(el)},260)},4500)}
