// Identidad comercial: el número consecutivo viaja con el cliente y todos sus documentos.
function sellerIdentityForRecord(record={},fallback=currentActor()){
  const users=window.BioAccess?.getState?.().users||[];
  const user=users.find(item=>String(item.id)===String(record.ownerId||''))||users.find(item=>item.role==='seller'&&String(item.sellerNumber||'').toUpperCase()===String(record.ownerSellerNumber||'').toUpperCase())||users.find(item=>item.role==='seller'&&String(item.name||'').trim().toLowerCase()===String(record.ownerName||record.seller||'').trim().toLowerCase())||(fallback?.role==='seller'?fallback:null);
  return {ownerId:user?.id||record.ownerId||'',ownerName:user?.name||record.ownerName||record.seller||'',ownerSellerNumber:user?.sellerNumber||record.ownerSellerNumber||''};
}
function normalizeCommercialSellerIdentity(){
  clients.forEach(client=>Object.assign(client,sellerIdentityForRecord(client,null)));
  quotations.forEach(quotation=>{const client=clients.find(item=>clientMatchesName(item,quotation.client));Object.assign(quotation,sellerIdentityForRecord({...quotation,...(client||{})},null));});
  commercialOrders.forEach(order=>{const client=clients.find(item=>clientMatchesName(item,order.client));Object.assign(order,sellerIdentityForRecord({...order,...(client||{})},null));});
}
const saveWithCommercialSellerIdentity=save;
save=function(){normalizeCommercialSellerIdentity();return saveWithCommercialSellerIdentity()};
