upsertClientFromQuotation=function(quotation){const client=clients.find(item=>clientMatchesName(item,quotation.client));Object.assign(quotation,sellerIdentityForRecord({...quotation,...(client||{})}));return upsertClientWithCommercialSellerIdentity(quotation)};
