$('#clientTransferForm')?.addEventListener('submit',()=>{const client=clients.find(item=>item.id===$('#clientTransferId')?.value),target=(window.BioAccess?.getState?.().users||[]).find(user=>String(user.id)===String($('#clientTransferOwner')?.value));if(!client||target?.role!=='seller')return;Object.assign(client,{ownerSellerNumber:target.sellerNumber||''});quotations.filter(item=>clientMatchesName(client,item.client)).forEach(item=>Object.assign(item,{ownerSellerNumber:target.sellerNumber||''}));commercialOrders.filter(item=>clientMatchesName(client,item.client)).forEach(item=>Object.assign(item,{ownerSellerNumber:target.sellerNumber||''}));save();});
const renderQuotationHistoryWithCommercialIdentity=renderQuotationHistory;
renderQuotationHistory=function(query=''){renderQuotationHistoryWithCommercialIdentity(query);document.querySelectorAll('#quotationHistory .quotation-history-row').forEach(row=>{const quotation=quotations.find(item=>String(row.querySelector('strong')?.textContent||'').startsWith(String(item.id)));if(!quotation)return;const identity=sellerIdentityForRecord(quotation,null),details=row.querySelector('div small');if(details)details.textContent=[quotation.contact,identity.ownerSellerNumber&&`${identity.ownerSellerNumber} · ${identity.ownerName||quotation.seller||''}`].filter(Boolean).join(' · ')||'Sin vendedor';if(!canManageQuotation(quotation))row.querySelectorAll('[data-edit-quotation],[data-delete-quotation],[data-convert-quotation]').forEach(button=>button.remove());});lucide.createIcons()};
const renderCommercialOrdersWithSharedVisibility=renderCommercialOrders;
renderCommercialOrders=function(query=''){const activeActor=currentActor;currentActor=()=>({...activeActor(),role:'administrator'});try{renderCommercialOrdersWithSharedVisibility(query)}finally{currentActor=activeActor}document.querySelectorAll('#commercialOrderList .commercial-order-row').forEach(row=>{const order=commercialOrders.find(item=>String(row.querySelector('strong')?.textContent||'').startsWith(String(item.id)));if(!order)return;const identity=sellerIdentityForRecord(order,null),details=row.querySelector('div small');if(details)details.textContent=`${details.textContent} · Vendedor: ${identity.ownerSellerNumber||'Sin número'}${identity.ownerName?` · ${identity.ownerName}`:''}`;if(!canManageQuotation(order))row.querySelectorAll('[data-edit-internal-order],[data-workflow-activate-internal-order],[data-continue-commercial-order]').forEach(button=>button.remove())});lucide.createIcons()};
