// La partida, el resumen y los documentos comparten la misma precisión contable.
const renderQuotationDraftWithSettledLineAmounts=renderQuotationDraft;
renderQuotationDraft=function(){renderQuotationDraftWithSettledLineAmounts();document.querySelectorAll('#quotationItems [data-quotation-line]').forEach(row=>{const item=quotationDraftItems.find(line=>line.catalogKey===row.dataset.quotationLine),amount=row.querySelector('.quotation-line-total');if(item&&amount)amount.textContent=money(quotationLineAmounts(item).total,item.currency)});refreshQuotationTotalsWithoutRedraw()};

