const quotationPaymentAccountText='con depósito o transferencia a nuestra cuenta bancaria BBVA No. 0112390566 CLABE 012680001123905664.';
const baseSyncQuotationPaymentTerms=syncQuotationPaymentTerms;syncQuotationPaymentTerms=function(){baseSyncQuotationPaymentTerms();const terms=$('#quotationPaymentTerms');if(terms&&!terms.value.includes('0112390566'))terms.value=`${terms.value.trim()} ${quotationPaymentAccountText}`.trim()};
function refineQuotationCommercialFields(){const validity=$('#quotationValidity')?.closest('.field')?.querySelector('span');if(validity)validity.textContent='Vigencia de la cotización';const rateField=$('#quotationExchangeRate')?.closest('.field');if(rateField){rateField.hidden=true;rateField.style.display='none'}syncQuotationPaymentTerms()}
refineQuotationCommercialFields();
let lastQuotationCreditDays=Number($('#quotationCreditDays')?.value||0);const paymentTermsWithCreditFix=syncQuotationPaymentTerms;syncQuotationPaymentTerms=function(){const creditSelect=$('#quotationCreditDays'),savedDays=creditSelect?.value,method=$('#quotationPaymentMethod')?.value,hasClient=Boolean(clients.find(item=>clientMatchesName(item,$('#quotationClient')?.value||'')));if(Number(savedDays)>0)lastQuotationCreditDays=Number(savedDays);const restoredDays=method==='credit'&&Number(savedDays)===0&&lastQuotationCreditDays>0?lastQuotationCreditDays:Number(savedDays||0);paymentTermsWithCreditFix();if(method==='credit'&&!hasClient&&creditSelect){creditSelect.value=String(restoredDays);lastQuotationCreditDays=restoredDays;const terms=$('#quotationPaymentTerms');if(terms)terms.value=terms.value.replace(/Crédito de \d+ días naturales/,`Crédito de ${restoredDays} días naturales`);const dueDate=new Date();dueDate.setDate(dueDate.getDate()+restoredDays);$('#quotationPaymentDate').value=dateInputValue(dueDate)}};
function quotationProtectedReference(item){const source=String(item.sourceCurrency||item.currency||'MXN').toUpperCase(),target=String(item.currency||source).toUpperCase(),sourcePrice=Number(item.sourcePrice??item.salePrice??0),storedConvertedPrice=Number(item.fx?.unitPrice);if(source!==target&&Number.isFinite(storedConvertedPrice)&&storedConvertedPrice>0)return storedConvertedPrice;if(source===target)return quotationProtectedPrice(sourcePrice).price;const conversion=quotationProductPrice({...item,sourceCurrency:source,sourcePrice},target);return Number(conversion?.unitPrice||0)}
function quotationPriceState(item){const reference=quotationProtectedReference(item),current=Number(item.unitPrice||0);if(!reference||Math.abs(current-reference)<.005)return 'protected';return current<reference?'below':'above'}
function applyQuotationPriceStates(){document.querySelectorAll('#quotationItems [data-quotation-line]').forEach(row=>{const item=quotationDraftItems.find(line=>line.catalogKey===row.dataset.quotationLine);if(!item)return;const state=quotationPriceState(item),price=row.querySelector('[data-field="unitPrice"]'),discount=row.querySelector('[data-field="discount"]');if(price){price.classList.remove('quotation-price-protected','quotation-price-below','quotation-price-above');price.classList.add(`quotation-price-${state}`)}if(discount){discount.classList.toggle('quotation-discount-active',Number(item.discount||0)>0);discount.classList.toggle('quotation-discount-clear',!Number(item.discount||0))}})}
const quotationDraftWithPriceStates=renderQuotationDraft;renderQuotationDraft=function(){quotationDraftWithPriceStates();applyQuotationPriceStates()};
function syncQuotationDiscountSummary(totals=quotationTotals()){const discount=$('#quotationDiscount'),row=discount?.closest('div'),hasDiscount=(totals.byCurrency||[]).some(entry=>Number(entry.discountTotal||0)>0);if(discount)discount.textContent=`− ${quotationAmountsLabel(totals,'discountTotal')}`;if(row){row.hidden=!hasDiscount;row.style.display=hasDiscount?'':'none'}}
function refreshQuotationTotalsWithoutRedraw(){const totals=quotationTotals(),itemCount=quotationDraftItems.length;$('#quotationSubtotal').textContent=quotationAmountsLabel(totals,'subtotal');syncQuotationDiscountSummary(totals);$('#quotationTaxAmount').textContent=quotationAmountsLabel(totals,'taxAmount');$('#quotationGrandTotal').textContent=quotationAmountsLabel(totals,'total');$('#quotationActionState').textContent=itemCount?`${itemCount} producto${itemCount===1?'':'s'} · ${quotationAmountsLabel(totals,'total')}`:'Agrega productos para emitir';renderQuotationAdvanceSummary()}
const parseQuotationNumericInput=value=>Number(String(value??'').replace(/,/g,''))||0;
const formatQuotationUnitPrice=value=>parseQuotationNumericInput(value).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
const renderQuotationDraftWithFormattedPrice=renderQuotationDraft;renderQuotationDraft=function(){renderQuotationDraftWithFormattedPrice();document.querySelectorAll('#quotationItems [data-field="unitPrice"]').forEach(input=>{input.type='text';input.inputMode='decimal';input.value=formatQuotationUnitPrice(input.value)});document.querySelectorAll('#quotationItems [data-field="discount"]').forEach(input=>{input.title='Descuento porcentual (%)';input.setAttribute('aria-label','Descuento porcentual (%)')});syncQuotationDiscountSummary()};
$('#quotationItems')?.addEventListener('input',event=>{const input=event.target.closest('.quotation-line-input');if(!input||!['unitPrice','discount'].includes(input.dataset.field))return;event.stopImmediatePropagation();const row=input.closest('[data-quotation-line]'),item=quotationDraftItems.find(line=>line.catalogKey===row?.dataset.quotationLine);if(!item)return;let value=parseQuotationNumericInput(input.value);if(input.dataset.field==='unitPrice')value=Math.max(0,value);if(input.dataset.field==='discount')value=Math.min(100,Math.max(0,value));item[input.dataset.field]=value;const line=row.querySelector('.quotation-line-total');if(line)line.textContent=money(quotationLineAmounts(item).total,item.currency);applyQuotationPriceStates();refreshQuotationTotalsWithoutRedraw()},true);
$('#quotationItems')?.addEventListener('blur',event=>{const input=event.target.closest('[data-field="unitPrice"]');if(!input)return;const row=input.closest('[data-quotation-line]'),item=quotationDraftItems.find(line=>line.catalogKey===row?.dataset.quotationLine);if(!item)return;item.unitPrice=Math.max(0,parseQuotationNumericInput(input.value));input.value=formatQuotationUnitPrice(item.unitPrice);refreshQuotationTotalsWithoutRedraw();applyQuotationPriceStates()},true);
['#quotationPaymentMethod','#quotationCreditDays'].forEach(selector=>$(selector)?.addEventListener('change',event=>{event.stopImmediatePropagation();syncQuotationPaymentTerms()},true));
