renderClients=function(query=''){renderClientsWithPortfolioOwner(query);const users=window.BioAccess?.getState?.().users||[];document.querySelectorAll('#clientList .client-dossier-row').forEach(row=>{const client=clients.find(item=>String(item.id)===String(row.dataset.clientDossierRow)),detail=row.firstElementChild;if(!client||!detail||detail.querySelector('.client-portfolio-owner'))return;const owner=users.find(user=>String(user.id)===String(client.ownerId));detail.insertAdjacentHTML('beforeend',`<small class="client-portfolio-owner">Responsable comercial: ${escapeHtml(owner?.name||client.ownerName||'Sin asignar')}</small>`)});};
